type XdgPopupError uint32

const (
	XdgPopupErrorInvalidGrab XdgPopupError = 0
)

// Request opcodes for xdg_popup
const (
	XdgPopupOpDestroy    uint16 = 0
	XdgPopupOpGrab       uint16 = 1
	XdgPopupOpReposition uint16 = 2
)

// Event opcodes for xdg_popup
const (
	XdgPopupEventOpConfigure    uint16 = 0
	XdgPopupEventOpPopupDone    uint16 = 1
	XdgPopupEventOpRepositioned uint16 = 2
)

// XdgPopupHandler represents the server-side request handler for xdg_popup.
type XdgPopupHandler interface {
	HandleDestroy(senderID uint32) error
	HandleGrab(senderID uint32, Seat uint32, Serial uint32) error
	HandleReposition(senderID uint32, Positioner uint32, Token uint32) error
}

// DispatchXdgPopup decodes incoming requests for xdg_popup and calls the handler.
func DispatchXdgPopup(r *wire.Reader, hdr wire.Header, h XdgPopupHandler) error {
	switch hdr.Opcode {
	case 0: // destroy
		return h.HandleDestroy(hdr.ObjectID)
	case 1: // grab
		argSeat, err := r.ReadUint32()
		if err != nil {
			return fmt.Errorf("failed reading xdg_popup.grab.seat: %w", err)
		}
		argSerial, err := r.ReadUint32()
		if err != nil {
			return fmt.Errorf("failed reading xdg_popup.grab.serial: %w", err)
		}
		return h.HandleGrab(hdr.ObjectID, argSeat, argSerial)
	case 2: // reposition
		argPositioner, err := r.ReadUint32()
		if err != nil {
			return fmt.Errorf("failed reading xdg_popup.reposition.positioner: %w", err)
		}
		argToken, err := r.ReadUint32()
		if err != nil {
			return fmt.Errorf("failed reading xdg_popup.reposition.token: %w", err)
		}
		return h.HandleReposition(hdr.ObjectID, argPositioner, argToken)
	default:
		return fmt.Errorf("unknown opcode %d for interface xdg_popup", hdr.Opcode)
	}
}

// SendXdgPopupConfigure writes a xdg_popup.configure event.
func SendXdgPopupConfigure(w *wire.Writer, targetID uint32, X int32, Y int32, Width int32, Height int32) error {
	start := w.BeginMessage(targetID, 0)
	if err := w.WriteInt32(X); err != nil {
		return err
	}
	if err := w.WriteInt32(Y); err != nil {
		return err
	}
	if err := w.WriteInt32(Width); err != nil {
		return err
	}
	if err := w.WriteInt32(Height); err != nil {
		return err
	}
	return w.EndMessage(start, targetID, 0)
}

// SendXdgPopupPopupDone writes a xdg_popup.popup_done event.
func SendXdgPopupPopupDone(w *wire.Writer, targetID uint32) error {
	start := w.BeginMessage(targetID, 1)
	return w.EndMessage(start, targetID, 1)
}

// SendXdgPopupRepositioned writes a xdg_popup.repositioned event.
func SendXdgPopupRepositioned(w *wire.Writer, targetID uint32, Token uint32) error {
	start := w.BeginMessage(targetID, 2)
	if err := w.WriteUint32(Token); err != nil {
		return err
	}
	return w.EndMessage(start, targetID, 2)
}
